function candles(){
 const i=current(),f=frames.indexOf(state.frame),height=Math.max(260,Math.round($('#screen').clientHeight-78)),plotBottom=height-32,plotTop=16,scale=(plotBottom-plotTop)/222;
 const Y=y=>plotTop+y*scale;let bars='',ema1=[],ema2=[],last=155;
 for(let n=0;n<43;n++){
  const close=160-n*2.05+Math.sin(n*.72+f)*17+Math.sin(n*2.1)*6,open=last,x=8+n*6.5,fill=close<open?'var(--up)':'var(--down)';
  bars+=`<line x1="${x+2}" x2="${x+2}" y1="${Y(Math.min(close,open)-6-n%5)}" y2="${Y(Math.max(close,open)+5+n%4)}" stroke="${fill}" stroke-width="1"/><rect x="${x}" y="${Y(Math.min(close,open))}" width="4" height="${Math.max(2,Math.abs(close-open)*scale)}" fill="${fill}" rx=".4"/><rect x="${x}" y="${Y(222-8-Math.abs(close-open)*.8)}" width="4" height="${(8+Math.abs(close-open)*.8)*scale}" fill="${fill}" opacity=".27"/>`;
  ema1.push(`${x+2},${Y(175-n*2.1+Math.sin(n*.25)*7)}`);ema2.push(`${x+2},${Y(184-n*1.75)}`);last=close;
 }
 return `<svg class="chart-svg" viewBox="0 0 360 ${height}" role="img" aria-label="${esc(i.name)} ${state.frame} 模拟 K 线，非真实行情"><text x="12" y="${height*.5}" style="font-size:23px;letter-spacing:4px;opacity:.08">MARKET WATCH</text>${[40,80,120,160,200].map(y=>`<line class="grid" x1="0" y1="${Y(y)}" x2="286" y2="${Y(y)}"/><text x="294" y="${Y(y)+3}">${num(i.price+(72-y)/40*(i.price*.0015),i.dec)}</text>`).join('')}${[44,106,168,230].map(x=>`<line class="grid" x1="${x}" x2="${x}" y1="${Y(0)}" y2="${plotBottom}"/>`).join('')}${bars}${state.indicators.includes('EMA 20')?`<polyline points="${ema1.join(' ')}" fill="none" stroke="#e1b775" stroke-width="1.3"/>`:''}${state.indicators.includes('EMA 60')?`<polyline points="${ema2.join(' ')}" fill="none" stroke="#859ee5" stroke-width="1.3"/>`:''}${state.indicators.includes('布林带')?`<polyline points="${ema1.map(p=>{const [x,y]=p.split(',');return `${x},${Number(y)-28*scale}`}).join(' ')}" fill="none" stroke="#9ea9ba" stroke-width="1" stroke-dasharray="4 3"/>`:''}<line x1="0" y1="${Y(72)}" x2="286" y2="${Y(72)}" stroke="var(--up)" stroke-dasharray="3 3" opacity=".7"/><rect x="289" y="${Y(72)-9}" width="71" height="19" rx="3" fill="var(--up)"/><text x="324" y="${Y(72)+4}" text-anchor="middle" style="fill:var(--bg);font-size:9px;font-weight:600">${num(i.price,i.dec)}</text><text x="9" y="${height-7}">06:00</text><text x="96" y="${height-7}">12:00</text><text x="185" y="${height-7}">18:00</text><text x="250" y="${height-7}">11 日</text></svg>`;
}
